<?php if(!$orders): ?><p>Chưa có đơn hàng.</p><?php else: ?><div class="table-wrap panel"><table><tr><th>Mã đơn</th><th>Khách hàng</th><th>Ngày</th><th>Tổng tiền</th><th>Trạng thái</th></tr><?php foreach($orders as $o): ?><tr><td><a href="/?page=order&id=<?= $o['id'] ?>">#<?= $o['id'] ?></a></td><td><?= e($o['name']) ?></td><td><?= e($o['created_at']) ?></td><td><?= money((int)$o['total']) ?></td><td><?= STATUSES[$o['status']] ?></td></tr><?php endforeach ?></table></div><?php endif ?>
